"""Generate the TypeScript types of the dashboard from the OpenAPI schema of the API (FR-24).

The dashboard never writes API types by hand: they come from the same models that produce the
responses, and a test fails when the committed file is out of date. The output is deterministic
(schemas sorted by name, properties in the order of the models).
"""

from __future__ import annotations

from typing import Any

from farejador.api.routes import create_api

HEADER = (
    "// Generated by scripts/gen_api_types.py from the OpenAPI schema of the API.\n"
    "// Do not edit by hand: run `uv run python scripts/gen_api_types.py` instead.\n"
)
_SKIPPED = {"HTTPValidationError", "ValidationError"}
_PRIMITIVES = {"string": "string", "integer": "number", "number": "number", "boolean": "boolean"}


def _literal(value: object) -> str:
    if isinstance(value, str):
        return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'
    return str(value).lower() if isinstance(value, bool) else str(value)


def _ts_type(schema: dict[str, Any]) -> str:
    if "$ref" in schema:
        return str(schema["$ref"]).rsplit("/", 1)[-1]
    if "enum" in schema:
        return " | ".join(_literal(value) for value in schema["enum"])
    for key in ("anyOf", "oneOf"):
        if key in schema:
            return " | ".join(_ts_type(option) for option in schema[key])
    if "allOf" in schema and len(schema["allOf"]) == 1:
        return _ts_type(schema["allOf"][0])
    kind = schema.get("type")
    if kind in _PRIMITIVES:
        return _PRIMITIVES[kind]
    if kind == "null":
        return "null"
    if kind == "array":
        inner = _ts_type(schema.get("items", {}))
        return f"readonly ({inner})[]" if " | " in inner else f"readonly {inner}[]"
    if kind == "object":
        if "properties" in schema:
            return _object_body(schema, indent="  ")
        return "Readonly<Record<string, unknown>>"
    return "unknown"


def _object_body(schema: dict[str, Any], indent: str = "") -> str:
    required = set(schema.get("required", []))
    lines = []
    for name, prop in schema.get("properties", {}).items():
        optional = "" if name in required else "?"
        lines.append(f"{indent}  readonly {name}{optional}: {_ts_type(prop)};")
    return "{\n" + "\n".join(lines) + f"\n{indent}}}"


def generate_types() -> str:
    """The content of ``web/src/api/types.ts``."""
    schemas: dict[str, dict[str, Any]] = create_api("/nonexistent").openapi()["components"][
        "schemas"
    ]
    blocks = [HEADER]
    for name in sorted(schemas):
        if name in _SKIPPED:
            continue
        schema = schemas[name]
        if "enum" in schema:
            blocks.append(f"export type {name} = {_ts_type(schema)};\n")
        else:
            blocks.append(f"export interface {name} {_object_body(schema)}\n")
    return "\n".join(blocks)
